import{_ as p,a0 as a,w as o,s as r,ao as u,I as i,a1 as n,A as l,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"如何在Ubuntu上使用MultiSystem创建多启动USB盘 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu上使用MultiSystem创建多启动USB盘 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu上使用MultiSystem创建多启动USB盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu上使用MultiSystem创建多启动USB盘 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem","title":"如何在Ubuntu上使用MultiSystem创建多启动USB盘","tag":"201501","desc":""},"relativePath":"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem.md","filePath":"[post].md"}'),m={name:"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem.md"};function d(S,t,b,y,g,M){const s=a("Link");return o(),r("div",null,[t[15]||(t[15]=u('<h1 id="如何在ubuntu上使用multisystem创建多启动usb盘" tabindex="-1">如何在Ubuntu上使用MultiSystem创建多启动USB盘 <a class="header-anchor" href="#如何在ubuntu上使用multisystem创建多启动usb盘" aria-label="Permalink to “如何在Ubuntu上使用MultiSystem创建多启动USB盘”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>也许还有不少人不知道<strong>MultiSystem</strong>，它是一个用来在Linux系统中创建多启动usb盘的小型的开源软件。使用这个工具，我们可以在USB中创建任意多的可启动Linux发行版。你所需要的只是网络链接（只在MultiSystem安装的时候需要），以及一个足够大的USB盘，这取决于你想在USB盘中放入发行版的数量。</p><h3 id="在-ubuntu-14-10-14-04-安装multisystem" tabindex="-1">在 Ubuntu 14.10/14.04 安装MultiSystem <a class="header-anchor" href="#在-ubuntu-14-10-14-04-安装multisystem" aria-label="Permalink to “在 Ubuntu 14.10/14.04 安装MultiSystem”">​</a></h3><h4 id="手动安装" tabindex="-1">手动安装: <a class="header-anchor" href="#手动安装" aria-label="Permalink to “手动安装:”">​</a></h4>',5)),i("p",null,[n(s,{href:"http://liveusb.info/multisystem/install-depot-multisystem.sh.tar.bz2"},{default:l(()=>[...t[0]||(t[0]=[e("下载 MultiSystem",-1)])]),_:1}),t[1]||(t[1]=e("脚本，并解压到任意地方。进入解压的地址，使用下面的命令运行脚本。",-1))]),t[16]||(t[16]=u(`<pre><code>sudo ./install-depot-multisystem.sh
</code></pre><h4 id="使用-ppa-安装" tabindex="-1">使用 PPA 安装: <a class="header-anchor" href="#使用-ppa-安装" aria-label="Permalink to “使用 PPA 安装:”">​</a></h4><p>当然，你也可以用下面的命令来更简单地使用PPA来安装MultiSystem。</p><pre><code>sudo apt-add-repository &#39;deb http://liveusb.info/multisystem/depot all main&#39;
wget -q -O - http://liveusb.info/multisystem/depot/multisystem.asc | sudo apt-key add -
sudo apt-get update
sudo apt-get install multisystem
</code></pre><p>安装完之后，它会自动打开MultiSystem。只要点击关闭按钮退出。</p><h3 id="安装之后" tabindex="-1">安装之后 <a class="header-anchor" href="#安装之后" aria-label="Permalink to “安装之后”">​</a></h3><p>MultiSystem 安装完成后，可以插入你的USB，并通过Unity Dash或者菜单运行MultiSystem。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Menu_0012.png" alt=""></p><p>第一次启动时，MultiSystem界面看起来会像下面这样。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_002.png" alt=""></p><p>选择USB设备，点击<strong>确认</strong>按钮。如果你看到下面的错误窗口，不必担心，它说的是USB设备没有标签。点击OK让MultiSystem自动设置标签。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Error_003.png" alt=""></p><p>那么，拔出/重新插入USB，再次运行MultiSystem。选择USB盘，再次点击确认。现在，你被要求确认在USB中安装Grub2.点击OK继续。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/gtkdialog_004.png" alt=""></p><p>最终，你会高兴地看到MultiSystem的界面。现在，时候创建多启动USB盘。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_005.png" alt=""></p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>MultiSystem非常容易使用。将ISO文件拖入MultiSystem窗口中。如果不行的话，点击底部的<strong>cd 按钮</strong>来选择ISO文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_006.png" alt=""></p><p>现在，MultiSystem会从ISO中拷贝文件，并让USB可启动。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_007.png" alt=""></p><p>相似地，你可以在你的USB中加入任意多的发行版。我这次加入了两个Linux发行版：CentOS 6.5和Android。</p><p>加完ISO文件后，你会在MultiSystem的主窗口中看到可启动的发行版列表了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_008.png" alt=""></p><p>就是这样。我们的多启动USB盘就可以使用了。重启系统，并在BIOS中设置USB优先启动。选择你想要安装的发行版并开始安装系统。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/QEMU_009.png" alt=""></p><p>此外，MultiSystem含有一些其它的选项：</p><ul><li>Grub 设置</li><li>Grub 和 Burg 的bootloader更新</li><li>下载 LiveCD</li><li>VirtualBox 安装</li><li>格式化USB盘</li><li>还有更多选项</li></ul><p>这些额外选项可以在MultiSystem的<strong>菜单</strong>标签里面看到。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_010.png" alt=""></p><p>同样，你也可以在Ubuntu中使用QEMU或者Oracle VirtualBox测试多启动USB盘。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_011.png" alt=""></p><p>MultiSystem工具是我测试到现在最棒和最有用的一款工具。这款工具对那些想要在他们的机器上安装多个系统的人是非常有用的。在你外出的时候，你不必再携带CD/DVD袋了。只要买一个16GB或者32GB的USB就行，并下载所有你想要的系统，随心所欲的安装系统即可。</p><p>并且，一个对于Windows系统用户的好消息是它也支持Windows系统。我在Windows 7上测试过，它可以工作！</p><p>享受吧！</p><hr>`,36)),i("p",null,[t[3]||(t[3]=e("via: ",-1)),n(s,{href:"http://www.unixmen.com/create-multiboot-usb-ubuntu-using-multisystem/"},{default:l(()=>[...t[2]||(t[2]=[e("http://www.unixmen.com/create-multiboot-usb-ubuntu-using-multisystem/",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=e("作者：",-1)),n(s,{href:"http://www.unixmen.com/author/sk/"},{default:l(()=>[...t[4]||(t[4]=[e("SK",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const f=p(m,[["render",d]]);export{B as __pageData,f as default};
